function seedLanguage(language, cards) {
  const existsStmt = db.prepare('SELECT id FROM cards WHERE language = ? AND term = ?');
  const insertCard = db.prepare(
    `INSERT INTO cards (language, term, translation_ru, transcription, theme, example_sentence, status)
     VALUES (@language, @term, @translation_ru, @transcription, @theme, @example_sentence, 'backlog')`
  );

  let inserted = 0;
  const insertAll = db.transaction((items) => {
    for (const card of items) {
      if (existsStmt.get(language, card.term)) continue; // idempotent: skip if already imported
      insertCard.run({ language, ...card, transcription: card.transcription ?? null });
      inserted += 1;
    }
  });

  insertAll(cards);
  return inserted;
}

function seed() {
  const enInserted = seedLanguage('en', EN_CARDS);
  const kzInserted = seedLanguage('kz', KZ_CARDS);
  console.log(`Seeded ${enInserted} English backlog cards (${EN_CARDS.length - enInserted} already existed).`);
  console.log(`Seeded ${kzInserted} Kazakh backlog cards (${KZ_CARDS.length - kzInserted} already existed).`);
}

seed();
